from collections import Counter


def transform(grid):
    """Restore cells marked 3 from the grid's horizontal/vertical reflection symmetry."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3:
                continue
            rr, cc = h - 1 - r, w - 1 - c
            orbit = {(r, c), (r, cc), (rr, c), (rr, cc)}
            votes = [grid[y][x] for y, x in orbit if grid[y][x] != 3]
            if votes:
                out[r][c] = Counter(votes).most_common(1)[0][0]
    return out
